import unittest
from stock.lines import quantities
from stock.orders import reserve

class StockTests(unittest.TestCase):
    def test_duplicates_and_copy(self):
        lines = [{'sku':'a', 'quantity':2}, {'sku':'a', 'quantity':3}]
        inventory = {'a':8, 'b':0}
        self.assertEqual(quantities(lines), {'a':5})
        self.assertEqual(reserve(inventory, lines), {'a':3, 'b':0})
        self.assertEqual(inventory, {'a':8, 'b':0})
    def test_failure_preserves_stock(self):
        inventory = {'a':2}
        with self.assertRaises(ValueError):
            reserve(inventory, [{'sku':'a','quantity':3}])
        self.assertEqual(inventory, {'a':2})
    def test_boolean_is_not_a_quantity(self):
        with self.assertRaises(ValueError):
            quantities([{'sku':'a','quantity':True}])

