import unittest
from splices.core import replace_spans
from splices.batch import apply_documents

class SpliceTests(unittest.TestCase):
    def test_original_offsets(self):
        spans = [{'start':0,'end':1,'text':'LONG'}, {'start':3,'end':4,'text':'Z'}]
        self.assertEqual(replace_spans('abcd', spans), 'LONGbcZ')
    def test_overlap(self):
        with self.assertRaises(ValueError):
            replace_spans('abcd', [{'start':0,'end':3,'text':'x'}, {'start':2,'end':4,'text':'y'}])
    def test_document_copy(self):
        docs = {'a':'abc','b':'keep'}
        self.assertEqual(apply_documents(docs, {'a':[{'start':1,'end':2,'text':''}]}), {'a':'ac','b':'keep'})
        self.assertEqual(docs, {'a':'abc','b':'keep'})

